import { api } from '../context/AuthContext';

// Content API
export const contentAPI = {
  // Get daily affirmation
  getAffirmation: async () => {
    try {
      const response = await api.get('/api/content/affirmation');
      return response.data;
    } catch (error) {
      throw error.response?.data || error;
    }
  },

  // Get articles with filtering
  getArticles: async (category = '', page = 1, limit = 10) => {
    try {
      const params = new URLSearchParams();
      if (category) params.append('category', category);
      params.append('page', page);
      params.append('limit', limit);

      const response = await api.get(`/api/content/articles?${params}`);
      return response.data;
    } catch (error) {
      throw error.response?.data || error;
    }
  },

  // Get single article
  getArticleById: async (id) => {
    try {
      const response = await api.get(`/api/content/articles/${id}`);
      return response.data;
    } catch (error) {
      throw error.response?.data || error;
    }
  },

  // Get categories
  getCategories: async () => {
    try {
      const response = await api.get('/api/content/categories');
      return response.data;
    } catch (error) {
      throw error.response?.data || error;
    }
  },

  // Seed database (development only)
  seedDatabase: async () => {
    try {
      const response = await api.post('/api/content/seed');
      return response.data;
    } catch (error) {
      throw error.response?.data || error;
    }
  },
};

// Chat API
export const chatAPI = {
  // Get messages
  getMessages: async (limit = 50, before = null) => {
    try {
      const params = new URLSearchParams();
      params.append('limit', limit);
      if (before) params.append('before', before);

      const response = await api.get(`/api/chat/messages?${params}`);
      return response.data;
    } catch (error) {
      throw error.response?.data || error;
    }
  },

  // Send message
  sendMessage: async (message, isAnonymous = false) => {
    try {
      const response = await api.post('/api/chat/messages', {
        message,
        isAnonymous,
      });
      return response.data;
    } catch (error) {
      throw error.response?.data || error;
    }
  },

  // Delete message
  deleteMessage: async (messageId) => {
    try {
      const response = await api.delete(`/api/chat/messages/${messageId}`);
      return response.data;
    } catch (error) {
      throw error.response?.data || error;
    }
  },

  // Report message
  reportMessage: async (messageId) => {
    try {
      const response = await api.post(`/api/chat/messages/${messageId}/report`);
      return response.data;
    } catch (error) {
      throw error.response?.data || error;
    }
  },

  // Get chat stats
  getStats: async () => {
    try {
      const response = await api.get('/api/chat/stats');
      return response.data;
    } catch (error) {
      throw error.response?.data || error;
    }
  },
};

// SOS API
export const sosAPI = {
  // Create SOS alert
  createAlert: async (alertData) => {
    try {
      const response = await api.post('/api/sos/alert', alertData);
      return response.data;
    } catch (error) {
      throw error.response?.data || error;
    }
  },

  // Get my alerts
  getMyAlerts: async () => {
    try {
      const response = await api.get('/api/sos/my-alerts');
      return response.data;
    } catch (error) {
      throw error.response?.data || error;
    }
  },

  // Get specific alert
  getAlert: async (alertId) => {
    try {
      const response = await api.get(`/api/sos/alert/${alertId}`);
      return response.data;
    } catch (error) {
      throw error.response?.data || error;
    }
  },

  // Resolve alert
  resolveAlert: async (alertId) => {
    try {
      const response = await api.put(`/api/sos/alert/${alertId}/resolve`);
      return response.data;
    } catch (error) {
      throw error.response?.data || error;
    }
  },

  // Get emergency resources
  getResources: async () => {
    try {
      const response = await api.get('/api/sos/resources');
      return response.data;
    } catch (error) {
      throw error.response?.data || error;
    }
  },
};

export default {
  content: contentAPI,
  chat: chatAPI,
  sos: sosAPI,
};
